"""Registrations: business licences, statutory, NGO, other."""

ENTITY = [('PAN of the business', 'Or of the proprietor.'), ('Certificate of incorporation or deed', 'For companies, LLPs and firms.'),
          ('KYC of the owner or signatory', 'PAN, Aadhaar and photograph.'), ('Business address proof', 'Utility bill plus rent agreement or NOC.')]
NGO = [('Registration certificate', 'Trust deed, society registration or Section 8 incorporation certificate.'), ('Trust deed or MoA', 'And rules or bye-laws, if any.'),
       ('PAN of the organisation', 'In the entity\'s own name.'), ('Trustee or director KYC', 'PAN and Aadhaar.'),
       ('Activity report', 'Notes on activities carried out so far, with photographs if available.'), ('Financial statements', 'For the last three years, if the organisation has been running.')]
REG_STEPS = [('Eligibility check', 'We confirm the registration applies to you and list the documents.'),
             ('Documents', 'You share the documents on WhatsApp. We review them for gaps.'),
             ('Application', 'We prepare and file the application with the authority.'),
             ('Certificate', 'We follow up on queries and deliver the certificate.')]

